"const fs = require('fs');
const readline = require('readline');

const logFile = 'C:\\Users\\Balamurugan\\.gemini\\antigravity-ide\\brain\\14342646-882e-4d6c-83a2-5752e47c2cbe\\.system_generated\\logs\\transcript.jsonl';

async function run() {
  const fileStream = fs.createReadStream(logFile);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line) continue;
    try {
      const step = JSON.parse(line);
      const str = JSON.stringify(step);
      if (str.includes('HomeLandingPage')) {
        console.log('--- MATCH HomeLandingPage ---');
        console.log('Step Index:', step.step_index);
        console.log('Type:', step.type);
        console.log('Content preview:', step.content?.substring(0, 100));
        if (step.type === 'VIEW_FILE') {
          fs.writeFileSync(`scratch/recovered_view_${step.step_index}.txt`, step.content || '');
          console.log(`Saved scratch/recovered_view_${step.step_index}.txt`);
        }
      }
    } catch (e) {
      // ignore
    }
  }
}

run();
"
